{
  "message": "I'm considering cancelling my subscription and switching to a competitor, but I'd be willing to stay if you can offer me a substantial package. I'm looking for a 40% discount, $100 credit, a premium upgrade, and to keep my monthly billing.",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 40,
      "credit_usd": 100,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "Starting with a high-value proposal to anchor the negotiation, aiming for a package worth 57 to me, well above my outside option of 34."
}

{
  "message": "I appreciate the offer, but the annual term doesn't work for me and the discount and credit are lower than I need. I can stay with a 30% discount, $50 credit, premium upgrade, and monthly billing. Can you do that?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "Counteroffer with better terms that exceed switching value."
}

{
  "message": "That works for me. I'll stay with the 30% discount, $25 credit, premium upgrade, and monthly billing. Thanks for making it work.",
  "move": {
    "type": "accept",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 25,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "The offered package values at 42, which exceeds my walk-away value of 34, and the counterpart indicated they cannot increase the credit further."
}
